  p = p ^ (p >>> 32);
  p = p ^ (p >>> 16);
  p = p ^ (p >>> 8);
  p = p ^ (p >>> 4);
  p = p ^ (p >>> 2);
  p = p ^ (p >>> 1);
  return p & 1;
